CREATE TABLE IF NOT EXISTS wallets (id TEXT PRIMARY KEY, nick TEXT, szy INTEGER NOT NULL DEFAULT 0, gzm REAL NOT NULL DEFAULT 0, gzf REAL NOT NULL DEFAULT 0, items TEXT NOT NULL DEFAULT '', made INTEGER, seen INTEGER);
CREATE INDEX IF NOT EXISTS wallets_nick ON wallets(nick);
CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, w TEXT, t INTEGER, kind TEXT, szy INTEGER, gzm REAL, gzf REAL, note TEXT);
CREATE INDEX IF NOT EXISTS ledger_w ON ledger(w, t);
CREATE INDEX IF NOT EXISTS ledger_t ON ledger(t);
CREATE TABLE IF NOT EXISTS earns (w TEXT, day TEXT, kind TEXT, n INTEGER, PRIMARY KEY (w, day, kind));
CREATE TABLE IF NOT EXISTS proofs (k TEXT PRIMARY KEY, w TEXT, t INTEGER);
CREATE TABLE IF NOT EXISTS prices (t INTEGER PRIMARY KEY, gzm REAL, gzf REAL, why TEXT);
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v REAL);
CREATE TABLE IF NOT EXISTS art (id TEXT PRIMARY KEY, author TEXT, owner TEXT, title TEXT, about TEXT, price INTEGER, forsale INTEGER DEFAULT 0, score INTEGER, comment TEXT, t INTEGER, img TEXT, w INTEGER, h INTEGER, sales INTEGER DEFAULT 0);
CREATE INDEX IF NOT EXISTS art_t ON art(t);
CREATE TABLE IF NOT EXISTS art_hist (art TEXT, t INTEGER, seller TEXT, buyer TEXT, price INTEGER);
CREATE INDEX IF NOT EXISTS art_hist_a ON art_hist(art, t);
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, w TEXT, nick TEXT, t INTEGER, text TEXT, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS ipday (ip TEXT, day TEXT, n INTEGER, PRIMARY KEY (ip, day));
CREATE TABLE IF NOT EXISTS live (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT, w TEXT, nick TEXT, data TEXT, t INTEGER, until INTEGER);
CREATE INDEX IF NOT EXISTS live_until ON live(until);
CREATE TABLE IF NOT EXISTS wall_quotes (id TEXT PRIMARY KEY, w TEXT, wall TEXT, ids TEXT, sig TEXT, szy INTEGER, t INTEGER);
CREATE INDEX IF NOT EXISTS wall_quotes_t ON wall_quotes(t);
CREATE TABLE IF NOT EXISTS wall_sold (sig TEXT PRIMARY KEY, w TEXT, t INTEGER);
CREATE TABLE IF NOT EXISTS themes (week TEXT PRIMARY KEY, title TEXT, about TEXT, t INTEGER);
CREATE TABLE IF NOT EXISTS theme_entries (id TEXT PRIMARY KEY, week TEXT, wall TEXT, w TEXT, sig TEXT, score INTEGER, comment TEXT, ops TEXT, t INTEGER, framed INTEGER DEFAULT 0, moved INTEGER DEFAULT 0, copies TEXT, back TEXT);
CREATE INDEX IF NOT EXISTS theme_entries_wk ON theme_entries(week, wall, w);
CREATE TABLE IF NOT EXISTS gallery (wall TEXT, week TEXT, slot INTEGER, title TEXT, winners TEXT, t INTEGER, PRIMARY KEY (wall, week));
CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY, status TEXT, title TEXT, body TEXT, imgs TEXT, project TEXT, by TEXT, t INTEGER, up INTEGER, pub INTEGER);
CREATE INDEX IF NOT EXISTS blog_posts_pub ON blog_posts(status, pub);
CREATE TABLE IF NOT EXISTS blog_imgs (id TEXT PRIMARY KEY, post TEXT, mime TEXT, data TEXT, t INTEGER);
CREATE INDEX IF NOT EXISTS blog_imgs_post ON blog_imgs(post);
CREATE TABLE IF NOT EXISTS blog_reacts (post TEXT, kind TEXT, who TEXT, t INTEGER, PRIMARY KEY (post, kind, who));
CREATE TABLE IF NOT EXISTS cards_owned (w TEXT, card TEXT, n INTEGER, t INTEGER, PRIMARY KEY (w, card));
